export const PROJECT_KEY_MAX_LENGTH = 4;

/**
 * Makes a project key unique within `taken` the way `uniqueSlug` does for
 * addresses: append `2`, `3`, … and trim the base so the key never grows past
 * `PROJECT_KEY_MAX_LENGTH` characters (`WV` → `WV2`, `WEBX` → `WEB2`).
 */
export function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const used = new Set(taken);
  if (!used.has(key)) return key;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const tail = String(suffix);
    const candidate = `${key.slice(0, PROJECT_KEY_MAX_LENGTH - tail.length)}${tail}`;
    if (!used.has(candidate)) return candidate;
  }
  throw new InvalidSlugError(key, "exhausted unique suffixes");
}

/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */

