import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { OrgId } from "@/types/common";

function projectInput(orgId: OrgId, name: string, slug: string, key: string): CreateProjectInput {
  return {
    orgId,
    name,
    slug,
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("services/project-service lifecycle", () => {
  it("makes a taken key unique, archived projects included", async () => {
    const tenant = await createTenant("keyunique", "growth");
    const admin = tenant.actors.admin;

    const vendors = await projectService.createProject(
      admin,
      projectInput(tenant.org.id, "Web Vendors", "web-vendors", "WV"),
    );
    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId: vendors.id,
      archiveIssues: false,
    });

    const visitors = await projectService.createProject(
      admin,
      projectInput(tenant.org.id, "Web Visitors", "web-visitors", "WV"),
    );
    expect(visitors.key).toBe("WV2");

    const plat = await projectService.createProject(
      admin,
      projectInput(tenant.org.id, "Platform Two", "platform-two", "PLAT"),
    );
    expect(plat.key).toBe("PLA2");
  });

  it("keeps an archived project's address reserved so it can be restored", async () => {
    const tenant = await createTenant("addrreserved", "growth");
    const admin = tenant.actors.admin;

    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    const created = await projectService.createProject(
      admin,
      projectInput(tenant.org.id, "Platform", "platform", "PLAT"),
    );
    expect(created.slug).toBe("platform-2");

    const restored = await projectService.restoreProject(admin, tenant.org.id, tenant.project.id);
    expect(restored.slug).toBe("platform");
  });

  it("frees a plan slot on archive and refuses a restore that has no room", async () => {
    const tenant = await createTenant("planslots", "free");
    const admin = tenant.actors.admin;

    const second = await projectService.createProject(
      admin,
      projectInput(tenant.org.id, "Second Project", "second", "SEC"),
    );
    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId: second.id,
      archiveIssues: false,
    });

    const third = await projectService.createProject(
      admin,
      projectInput(tenant.org.id, "Third Project", "third", "THI"),
    );

    const restored: unknown[] = [];
    const off = subscribe("project.restored", (payload) => {
      restored.push(payload);
    });
    try {
      await expect(
        projectService.restoreProject(admin, tenant.org.id, second.id),
      ).rejects.toThrow(/allows 2 projects/);
      expect(restored).toHaveLength(0);
      expect((await projectRepo.findProjectById(tenant.org.id, second.id))?.archivedAt).not.toBeNull();
    } finally {
      off();
    }

    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId: third.id,
      archiveIssues: false,
    });
    await projectService.restoreProject(admin, tenant.org.id, second.id);
    expect(await projectRepo.countProjects(tenant.org.id)).toBe(2);
  });

  it("moves the projects meter on restore and agrees with the recount", async () => {
    const off = registerUsageListeners();
    try {
      const tenant = await createTenant("meter", "growth");
      const admin = tenant.actors.admin;
      await usageRepo.recomputeUsage(tenant.org.id);

      await projectService.archiveProject(admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        archiveIssues: false,
      });
      expect((await usageRepo.getUsage(tenant.org.id)).projectsUsed).toBe(0);

      await projectService.restoreProject(admin, tenant.org.id, tenant.project.id);
      expect((await usageRepo.getUsage(tenant.org.id)).projectsUsed).toBe(1);
      expect((await usageRepo.recomputeUsage(tenant.org.id)).projectsUsed).toBe(1);
    } finally {
      off();
    }
  });

  it("refuses to restore a project that is not archived and announces nothing", async () => {
    const tenant = await createTenant("restorelive", "growth");

    const received: unknown[] = [];
    const off = subscribe("project.restored", (payload) => {
      received.push(payload);
    });
    try {
      await expect(
        projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id),
      ).rejects.toThrow(/not archived/);
      expect(received).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("restores a project with the status it had", async () => {
    const tenant = await createTenant("restorestatus", "growth");
    const admin = tenant.actors.admin;

    await projectService.updateProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "paused",
    });
    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    const restored = await projectService.restoreProject(admin, tenant.org.id, tenant.project.id);
    expect(restored.status).toBe("paused");
  });

  it("saves the status and reports it through the status filter", async () => {
    const tenant = await createTenant("statussaved", "growth");
    const admin = tenant.actors.admin;

    const updated = await projectService.updateProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "paused",
    });
    expect(updated.status).toBe("paused");

    const paused = await projectService.listProjects(admin, {
      orgId: tenant.org.id,
      status: "paused",
      limit: 20,
      cursor: null,
    });
    expect(paused.items.map((row) => row.project.id)).toEqual([tenant.project.id]);
  });

  it("refuses new issues in a paused or completed project", async () => {
    const tenant = await createTenant("statusissues", "growth");
    const admin = tenant.actors.admin;

    await projectService.updateProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "paused",
    });

    const created: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      created.push(payload);
    });
    try {
      await expect(
        issueService.createIssue(
          tenant.actors.member,
          issueInput(tenant.org.id, tenant.project.id),
        ),
      ).rejects.toThrow(/paused/);
      expect(created).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("completes a project only when none of its issues is open", async () => {
    const tenant = await createTenant("statuscomplete", "growth");
    const admin = tenant.actors.admin;
    const orgId = tenant.org.id;
    const projectId = tenant.project.id;

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId, projectId),
    );

    await expect(
      projectService.updateProject(admin, {
        orgId,
        projectId,
        name: "Renamed while refused",
        status: "completed",
      }),
    ).rejects.toThrow(/open/);
    const unchanged = await projectRepo.findProjectById(orgId, projectId);
    expect(unchanged?.status).toBe("active");
    expect(unchanged?.name).not.toBe("Renamed while refused");

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId,
      issueId: issue.id,
      status: "done",
    });
    const completed = await projectService.updateProject(admin, {
      orgId,
      projectId,
      status: "completed",
    });
    expect(completed.status).toBe("completed");

    // Existing issues can still be worked on, and completing again is a no-op.
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId,
      issueId: issue.id,
      status: "todo",
    });
    const again = await projectService.updateProject(admin, {
      orgId,
      projectId,
      status: "completed",
    });
    expect(again.status).toBe("completed");

    const reactivated = await projectService.updateProject(admin, {
      orgId,
      projectId,
      status: "active",
    });
    expect(reactivated.status).toBe("active");
  });

  it("does not count archived issues as open", async () => {
    const tenant = await createTenant("statusarchived", "growth");
    const admin = tenant.actors.admin;

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id),
    );
    const other = await projectService.createProject(
      admin,
      projectInput(tenant.org.id, "Other Work", "other-work", "OTH"),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, other.id),
    );

    // Archiving the issue frees `other` to be completed, not the first project.
    const issues = await projectService.listProjects(admin, {
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(issues.items.find((row) => row.project.id === other.id)?.stats.openIssues).toBe(1);
  });

  it("refuses a status change on an archived project", async () => {
    const tenant = await createTenant("statusarchivedproj", "growth");
    const admin = tenant.actors.admin;

    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      projectService.updateProject(admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        status: "paused",
      }),
    ).rejects.toThrow(/archived/);
  });
});
