    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    const restored = await projectService.restoreProject(admin, tenant.org.id, tenant.project.id);
    expect(restored.status).toBe("paused");
  });

  it("saves the status and reports it through the status filter", async () => {
    const tenant = await createTenant("statussaved", "growth");
    const admin = tenant.actors.admin;

    const updated = await projectService.updateProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "paused",
    });
    expect(updated.status).toBe("paused");

    const paused = await projectService.listProjects(admin, {
      orgId: tenant.org.id,
      status: "paused",
      limit: 20,
      cursor: null,
    });
    expect(paused.items.map((row) => row.project.id)).toEqual([tenant.project.id]);
  });

  it("refuses new issues in a paused or completed project", async () => {
    const tenant = await createTenant("statusissues", "growth");
    const admin = tenant.actors.admin;

    await projectService.updateProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "paused",
    });

    const created: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      created.push(payload);
    });
    try {
      await expect(
        issueService.createIssue(
          tenant.actors.member,
          issueInput(tenant.org.id, tenant.project.id),
        ),
      ).rejects.toThrow(/paused/);
      expect(created).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("completes a project only when none of its issues is open", async () => {
    const tenant = await createTenant("statuscomplete", "growth");
    const admin = tenant.actors.admin;
    const orgId = tenant.org.id;
    const projectId = tenant.project.id;

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId, projectId),
    );

    await expect(
      projectService.updateProject(admin, {
        orgId,
        projectId,
        name: "Renamed while refused",
        status: "completed",
      }),
    ).rejects.toThrow(/open/);
    const unchanged = await projectRepo.findProjectById(orgId, projectId);
    expect(unchanged?.status).toBe("active");
    expect(unchanged?.name).not.toBe("Renamed while refused");

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId,
      issueId: issue.id,
      status: "done",
    });
    const completed = await projectService.updateProject(admin, {
      orgId,
      projectId,
      status: "completed",
    });
    expect(completed.status).toBe("completed");

    // Existing issues can still be worked on, and completing again is a no-op.
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId,
      issueId: issue.id,
      status: "todo",
    });
    const again = await projectService.updateProject(admin, {
      orgId,
      projectId,
      status: "completed",
    });
    expect(again.status).toBe("completed");

    const reactivated = await projectService.updateProject(admin, {
      orgId,
      projectId,
      status: "active",
    });
    expect(reactivated.status).toBe("active");
  });

  it("does not count archived issues as open", async () => {
    const tenant = await createTenant("statusarchived", "growth");
    const admin = tenant.actors.admin;

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id),
    );
    const other = await projectService.createProject(
      admin,
      projectInput(tenant.org.id, "Other Work", "other-work", "OTH"),
    );
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, other.id),
    );

    // Archiving the issue frees `other` to be completed, not the first project.
    const issues = await projectService.listProjects(admin, {
      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(issues.items.find((row) => row.project.id === other.id)?.stats.openIssues).toBe(1);
  });

  it("refuses a status change on an archived project", async () => {
    const tenant = await createTenant("statusarchivedproj", "growth");
    const admin = tenant.actors.admin;

    await projectService.archiveProject(admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      projectService.updateProject(admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        status: "paused",
      }),
    ).rejects.toThrow(/archived/);
  });
});
